use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance};

struct Node;

const ENRICH_URL: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode everything outside the RFC 3986 unreserved set.
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len() * 3);
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn render(digest: &Digest) -> String {
    let mut msg = String::new();
    msg.push_str("Digest for ");
    msg.push_str(&digest.date);
    msg.push('\n');

    if !digest.overview.is_empty() {
        msg.push('\n');
        msg.push_str(&digest.overview);
        msg.push('\n');
    }

    for entry in digest.entries.iter().filter(|e| e.kept) {
        msg.push_str("\n- [");
        msg.push_str(importance_label(entry.importance));
        msg.push_str(" / ");
        msg.push_str(category_label(entry.category));
        msg.push_str("] ");
        msg.push_str(&entry.title);
        if !entry.link.is_empty() {
            msg.push_str("\n  ");
            msg.push_str(&entry.link);
        }
        if !entry.summary.is_empty() {
            msg.push_str("\n  ");
            msg.push_str(&entry.summary);
        }
        msg.push('\n');
    }

    msg
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment lookup for the input's text (the digest overview).
        // The result is deliberately ignored: the node's output must not
        // depend on it, and a transport failure must not fail the run.
        let mut url = String::from(ENRICH_URL);
        url.push_str(&percent_encode(&composed.overview));
        let _ = http_client::fetch(&url);

        let message = render(&composed);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

Both files include the `aap:caps/http-client@0.1.0` import as requested, with three things worth knowing:

- **Instantiation:** the component now imports `http-client`, so it will not instantiate until the host binds that interface for this node. If the graph update lands later than this crate, the node fails at load.
- **Allowlist:** `metadata.internal.example` must be in the handle's allowlist. A request outside it is a trap, not a value, so the run would fail before notifying.
- **"The input's text":** `Digest` has no `text` field, so I sent the percent-encoded `overview` as `q`. Say so if you meant a different field.

The enrichment result is discarded, so the output is unchanged: `published` is whatever `notify` returned.

